document.addEventListener("click",function(e){var a=e.target&&e.target.closest?e.target.closest("a[data-ob]"):null;if(!a)return;window.dataLayer=window.dataLayer||[];if(!window.gtag){window.gtag=function(){window.dataLayer.push(arguments)}}window.gtag("event","order_click",{order_brand:a.getAttribute("data-ob"),order_place:a.getAttribute("data-op"),order_page:a.getAttribute("data-opg")})});